1import { useState } from "react";
2
3import Header from "./components/Header";
4import EntryCard from "./components/EntryCard";
5import JournalForm from "./components/JournalForm";
6
7function App() {
8
9  const [entries, setEntries] = useState([]); // or your existing seed entry
10
11  function handleAddEntry(title, content) {
12    const newEntry = {
13      id: Date.now(),
14      title,
15      content,
16      date: new Date().toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }).toUpperCase(),
17      author: "John Doe"
18    };
19
20    setEntries([...entries, newEntry]);
21  }
22
23  function handleEdit(id, newTitle, newContent) {
24    setEntries(
25      entries.map((entry) =>
26        entry.id === id
27          ? { ...entry, title: newTitle, content: newContent }
28          : entry
29      )
30    );
31  }
32
33  function handleDelete(id) {
34    setEntries(entries.filter((entry) => entry.id !== id));
35  }
36
37  return (
38    <div className="main-container">
39      <Header />
40      <JournalForm onAddEntry={handleAddEntry} />
41
42      <section className="entries-section">
43        <div className="entry-list-header">
44          <h3 className="entries-section-title">Recent Entries</h3>
45           <span className="entry-count">
46              {entries.length} {entries.length === 1 ? 'entry' : 'entries'}
47           </span>
48         </div>
49        {entries.length === 0 ? (
50          <p className="empty-state">No entries yet. Add one above.</p>
51        ) : (
52          entries.map((entry) => (
53            <EntryCard
54              key={entry.id}
55              id={entry.id}
56              title={entry.title}
57              date={entry.date}
58              content={entry.content}
59              author={entry.author}
60              onDelete={handleDelete}
61               onEdit={handleEdit}
62            />
63          ))
64        )}
65      </section>
66    </div>
67  );
68}
69
70export default App;

